"use client";
import { ArtemisScope } from "./artemis-scope";
import Variant1 from "./components/data-table/variants/02-default";
const variants = { default: Variant1 };
export interface ArtemisDataTableProps {
  className?: string;
  variant?: "default";
}
export function ArtemisDataTable({ className, variant = "default" }: ArtemisDataTableProps) {
  const View = variants[variant];
  return (
    <ArtemisScope className={`art:[&>*]:mx-auto ${className ?? ""}`}>
      <View />
    </ArtemisScope>
  );
}

"use client";
// @zeus-internal
import { useId, useMemo, useState } from "react";
import { sortRows, tableRows, type SortKey } from "./02-default/data";
import { TableCheckbox } from "./02-default/table-checkbox";
import { TableRow } from "./02-default/table-row";
const headings: {
    label: string;
    key: SortKey;
    align: string;
}[] = [
    { label: "Customer", key: "customer", align: "art:text-left" },
    { label: "Plan", key: "plan", align: "art:text-center" },
    { label: "Status", key: "status", align: "art:text-center" },
    { label: "Seats", key: "seats", align: "art:text-center" },
    { label: "Spend", key: "spend", align: "art:text-right" },
];
function SortGlyph({ active, direction }: {
    active: boolean;
    direction: "asc" | "desc";
}) {
    if (!active)
        return <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-chevrons-up-down art:size-3.5 art:opacity-45" aria-hidden="true"><path d="m7 15 5 5 5-5"/><path d="m7 9 5-5 5 5"/></svg>;
    return <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={`art:lucide art:lucide-chevron-${direction === "asc" ? "art:up" : "art:down"} art:size-3.5`} aria-hidden="true"><path d={direction === "asc" ? "m18 15-6-6-6 6" : "m6 9 6 6 6-6"}/></svg>;
}
export default function DataTableDefault() {
    const selectionId = useId();
    const [sort, setSort] = useState<{
        key: SortKey;
        direction: "asc" | "desc";
    }>({ key: "spend", direction: "desc" });
    const [scrollTop, setScrollTop] = useState(0);
    const [selected, setSelected] = useState<Set<number>>(() => new Set());
    const sorted = useMemo(() => sortRows(sort.key, sort.direction), [sort]);
    const start = Math.max(0, Math.floor(scrollTop / 60) - 8);
    const end = Math.min(sorted.length, Math.floor((scrollTop + 448) / 60) + 9);
    const selectionState = selected.size === 0 ? "unchecked" : selected.size === tableRows.length ? "checked" : "indeterminate";
    const changeSort = (key: SortKey) => setSort(previous => ({ key, direction: previous.key === key && previous.direction === "asc" ? "desc" : "asc" }));
    const toggleRow = (id: number) => setSelected(previous => {
        const next = new Set(previous);
        if (next.has(id))
            next.delete(id);
        else
            next.add(id);
        return next;
    });
    const toggleAll = () => setSelected(previous => previous.size === tableRows.length ? new Set() : new Set(tableRows.map(row => row.id)));
    return <div className="art:w-full art:overflow-hidden art:border art:border-border art:bg-background art:text-sm art:rounded-xl">
    <div className="art:overflow-auto art:[scrollbar-gutter:stable]" style={{ height: "448px" }} onScroll={event => setScrollTop(event.currentTarget.scrollTop)}>
      <table className="art:min-w-[760px] art:w-full art:table-fixed art:border-collapse">
        <colgroup><col className="art:w-11"/><col style={{ width: "38%" }}/><col style={{ width: "130px" }}/><col style={{ width: "130px" }}/><col style={{ width: "100px" }}/><col style={{ width: "120px" }}/></colgroup>
        <thead><tr>
          <th className="art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-3 art:text-center"><div className="art:flex art:items-center art:justify-center"><TableCheckbox id={selectionId} label="Select all visible rows" state={selectionState} onClick={toggleAll}/></div></th>
          {headings.map(({ label, key, align }) => <th key={key} scope="col" className={`art:sticky art:top-0 art:z-10 art:h-11 art:border-border art:border-b art:bg-muted art:px-4 art:font-medium art:text-muted-foreground art:text-xs ${align}`}><button type="button" onClick={() => changeSort(key)} className={`art:inline-flex art:min-h-10 art:items-center art:gap-1.5 art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring ${key === "spend" ? "art:ml-auto" : ""}`}>{label}<SortGlyph active={sort.key === key} direction={sort.direction}/></button></th>)}
        </tr></thead>
        <tbody>
          {start > 0 && <tr aria-hidden="true" style={{ height: `${start * 60}px` }}><td colSpan={6}/></tr>}
          {sorted.slice(start, end).map((row, offset) => <TableRow key={row.id} row={row} index={start + offset} selected={selected.has(row.id)} onToggle={() => toggleRow(row.id)}/>)}
          {end < sorted.length && <tr aria-hidden="true" style={{ height: `${(sorted.length - end) * 60}px` }}><td colSpan={6}/></tr>}
        </tbody>
      </table>
    </div>
  </div>;
}

// @zeus-internal
const people = [
    ["Sam Taylor", "sam.taylor"],
    ["Casey Reed", "casey.reed"],
    ["Morgan Wells", "morgan.wells"],
    ["Taylor Brooks", "taylor.brooks"],
    ["Jordan Lee", "jordan.lee"],
    ["Riley Park", "riley.park"],
    ["Quinn Avery", "quinn.avery"],
    ["Cameron Shaw", "cameron.shaw"],
] as const;
const plans = ["Business", "Starter", "Pro"] as const;
const statuses = ["Trial", "Active", "Paused"] as const;
export type TableRow = {
    id: number;
    name: string;
    email: string;
    plan: string;
    status: string;
    seats: number;
    spend: number;
};
export type SortKey = "customer" | "plan" | "status" | "seats" | "spend";
export const tableRows: TableRow[] = Array.from({ length: 10000 }, (_, index) => {
    const id = index + 1;
    const [name, emailPrefix] = people[id % people.length];
    return {
        id,
        name,
        email: `${emailPrefix}${id}@example.com`,
        plan: plans[id % plans.length],
        status: statuses[id % statuses.length],
        seats: 1 + 3 * ((id - 1) % people.length),
        spend: 29 + (((id - 1) * 47) % 1970),
    };
});
export function sortRows(key: SortKey, direction: "asc" | "desc"): TableRow[] {
    return [...tableRows].sort((left, right) => {
        const a = key === "customer" ? left.name : left[key];
        const b = key === "customer" ? right.name : right[key];
        const comparison = typeof a === "number" && typeof b === "number" ? a - b : String(a).localeCompare(String(b));
        return (direction === "asc" ? comparison : -comparison) || left.id - right.id;
    });
}

"use client";
// @zeus-internal
import { AnimatePresence, motion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../../lib/ease";
type CheckboxState = "unchecked" | "checked" | "indeterminate";
const base = "art:inline-flex art:h-5 art:w-5 art:shrink-0 art:items-center art:justify-center art:rounded-md art:border-2 art:outline-none art:transition-colors art:duration-200 art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:disabled:cursor-not-allowed art:disabled:opacity-60";
export function TableCheckbox({ id, label, state, onClick }: {
    id: string;
    label: string;
    state: CheckboxState;
    onClick: () => void;
}) {
    const selected = state !== "unchecked";
    return <label htmlFor={id} className="art:inline-flex art:items-center art:gap-3 art:cursor-pointer">
    <motion.button id={id} type="button" role="checkbox" aria-checked={state === "indeterminate" ? "mixed" : selected} aria-label={label} data-state={state} tabIndex={0} whileTap={{ scale: 0.92 }} onClick={onClick} className={`${base} ${selected ? "art:border-primary art:bg-primary art:text-primary-foreground" : "art:border-muted-foreground/50 art:bg-background art:hover:border-muted-foreground"}`}>
      <AnimatePresence initial={false}>{selected && <motion.svg key={state} width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" initial={{ opacity: 0, scale: 0.5 }} animate={{ opacity: 1, scale: 1 }} exit={{ opacity: 0, scale: 0.5 }} transition={{ duration: 0.16, ease: ARTEMIS_EASE_OUT }}>
        <title>{state === "indeterminate" ? "Partially selected" : "Selected"}</title>
        <motion.path d={state === "indeterminate" ? "M6 12h12" : "M5 13l4 4L19 7"} pathLength="1" strokeDasharray="1 1" initial={{ pathLength: 0 }} animate={{ pathLength: 1 }} transition={{ duration: state === "indeterminate" ? 0.28 : 0.22, delay: 0.04 }}/>
      </motion.svg>}</AnimatePresence>
    </motion.button>
  </label>;
}

"use client";
// @zeus-internal
import type { TableRow as Row } from "./data";
import { TableCheckbox } from "./table-checkbox";
export function TableRow({ row, index, selected, onToggle }: {
    row: Row;
    index: number;
    selected: boolean;
    onToggle: () => void;
}) {
    const checkboxId = `_r_${index.toString(32)}_`;
    const statusClass = row.status === "Active" ? "art:bg-primary art:text-primary-foreground" : row.status === "Trial" ? "art:bg-muted art:text-foreground" : "art:border art:border-border art:bg-background art:text-muted-foreground";
    return <tr className="art:border-border/70 art:border-b art:transition-colors art:last:border-b-0 art:hover:bg-muted/45 art:data-[selected]:bg-muted/70" style={{ height: "60px" }} data-selected={selected ? "true" : undefined}>
    <td className="art:relative art:p-0 art:text-center"><div className="art:absolute art:inset-0 art:flex art:items-center art:justify-center art:px-3"><TableCheckbox id={checkboxId} label={`Select row ${row.id}`} state={selected ? "checked" : "unchecked"} onClick={onToggle}/></div></td>
    <td className="art:relative art:p-0 art:text-foreground art:text-left"><div className="art:absolute art:inset-0 art:flex art:min-w-0 art:items-center art:overflow-hidden art:px-4 art:justify-start"><div className="art:min-w-0"><p className="art:truncate art:font-medium">{row.name}</p><p className="art:truncate art:text-muted-foreground art:text-xs">{row.email}</p></div></div></td>
    <td className="art:relative art:p-0 art:text-foreground art:text-center"><div className="art:absolute art:inset-0 art:flex art:min-w-0 art:items-center art:overflow-hidden art:px-4 art:justify-center">{row.plan}</div></td>
    <td className="art:relative art:p-0 art:text-foreground art:text-center"><div className="art:absolute art:inset-0 art:flex art:min-w-0 art:items-center art:overflow-hidden art:px-4 art:justify-center"><span className={`art:inline-flex art:rounded-full art:px-2.5 art:py-1 art:font-medium art:text-xs ${statusClass}`}>{row.status}</span></div></td>
    <td className="art:relative art:p-0 art:text-foreground art:text-center"><div className="art:absolute art:inset-0 art:flex art:min-w-0 art:items-center art:overflow-hidden art:px-4 art:justify-center"><span className="art:tabular-nums">{row.seats}</span></div></td>
    <td className="art:relative art:p-0 art:text-foreground art:text-right"><div className="art:absolute art:inset-0 art:flex art:min-w-0 art:items-center art:overflow-hidden art:px-4 art:justify-end"><span className="art:font-medium art:tabular-nums">{"$"}{row.spend.toLocaleString("en-US")}</span></div></td>
  </tr>;
}
